 function edit(calendar){if(!form)return;for(const key of ['id','code','name','kind','timeZoneId','coverageFrom','coverageThrough','source'])form.elements[key].value=calendar?.[key]??({kind:'work',timeZoneId:'Asia/Tehran'}[key]||'');form.elements.active.checked=calendar?.active??true;form.elements.reason.value='';$('org-weekly-windows').replaceChildren();$('org-date-exceptions').replaceChildren();for(const w of calendar?.weeklyWindows||[])weeklyRow(w);for(const e of calendar?.exceptions||[])exceptionRow(e);$('org-calendar-editor').open=true;form.elements.name.focus();}
 function render(){const list=$('org-calendar-list');list.replaceChildren();$('org-calendar-revision').textContent='نسخهٔ داده '+state.revision;for(const c of state.calendars){const card=node('article',null,'org-position');card.append(node('h4',c.name),node('span',c.active?'فعال':'غیرفعال','pill '+(c.active?'teal':'blue')),node('p',(c.kind==='work'?'تقویم کاری':'پنجرهٔ داده')+' · '+c.code),node('p','منطقهٔ زمانی: '+c.timeZoneId),coverage(c),node('small','مرجع: '+c.source));for(const w of c.weeklyWindows)card.append(node('p',days[w.dayOfWeek]+' · '+time(w.startMinute)+' تا '+time(w.endMinute)+(w.endMinute<w.startMinute?' · تا روز بعد':'')));if(!c.weeklyWindows.length)card.append(node('p','برنامهٔ هفتگی خالی؛ فقط استثناهای باز قابل استفاده‌اند.'));const details=node('details'),summary=node('summary',c.exceptions.length+' تعطیلی / استثنای ثبت‌شده');details.append(summary);for(const e of c.exceptions)details.append(node('p',e.date+' · '+(e.kind==='closed'?'تعطیل':e.windows.map(w=>time(w.startMinute)+' تا '+time(w.endMinute)).join('، '))+' · '+e.reason));card.append(details);if(form){const button=node('button','ویرایش دادهٔ تقویم','button secondary');button.type='button';button.onclick=()=>{edit(c);$('org-calendar-editor').scrollIntoView({block:'start',behavior:'auto'});};card.append(button);}list.append(card);}if(!state.calendars.length)list.append(node('p','هنوز تقویمی ثبت نشده است؛ منطقهٔ زمانی، هفته و تعطیلی‌های بررسی‌شده را تعریف کنید.','muted'));const old=probe.elements.calendarId.value;probe.elements.calendarId.replaceChildren(new Option('انتخاب تقویم',''));for(const c of state.calendars)probe.elements.calendarId.append(new Option(c.name+(c.active?'':' · غیرفعال'),c.id));if(state.calendars.some(x=>x.id===old))probe.elements.calendarId.value=old;probeMode();invalidate();}
