(() => {
 'use strict';
 const root=document.getElementById('organization-template');if(!root)return;
 const $=id=>document.getElementById(id),base='/api/organization/template',form=$('org-template-create'),run=$('org-template-run');let lessonByKey=new Map();
 function scenarioValue(label,value){const line=node('small'),isolated=node('bdi',String(value));isolated.dir='ltr';line.append(node('span',label),isolated);return line;}
 const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;};
 function message(text,error=false){$('org-template-message').textContent=text;$('org-template-message').className=error?'org-error':'org-success';}
 async function request(path='',body){const response=await fetch(base+path,body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':root.querySelector('[name=__RequestVerificationToken]').value},body:JSON.stringify(body)}:undefined);if(response.status===404&&!body&&!path)return null;if(!response.ok){let error;try{error=await response.json();}catch{}throw Error(error?.error||'دادهٔ آموزشی خوانده یا ثبت نشد.');}if(!response.headers.get('content-type')?.includes('application/json'))throw Error('نشست پایان یافته است؛ دوباره وارد شوید.');return response.json();}
 function render(view){lessonByKey=new Map((view?.lessons||[]).map(x=>[x.key,x.explanation]));form.hidden=!!view;run.hidden=!view;if(!view){message('سازمان الگو هنوز در این پایگاه داده ساخته نشده است.');return;}if(view.marker?.tenantId!==view.tenant?.id)throw Error('نشان آموزشی با سازمان دریافتی تطبیق ندارد.');const links=$('org-template-links');links.replaceChildren();for(const [route,label] of [['Organization','مشاهدهٔ ساختار و تقویم الگو'],['Governance','مشاهده و آزمایش سیاست‌های الگو']]){const a=node('a',label,'button secondary');a.href='/'+route+'?tenant='+encodeURIComponent(view.marker.tenantId);links.append(a);}const notes=$('org-template-notes');notes.replaceChildren();for(const note of view.notes||[])notes.append(node('p',note,'org-calendar-note'));const lessons=$('org-template-lessons');lessons.replaceChildren();for(const lesson of view.lessons||[]){const card=node('article',null,'org-position');card.append(node('h4',lesson.title),node('p',lesson.explanation),node('small','محل تنظیم: '+lesson.configurationArea));lessons.append(card);}message('سازمان الگو در پایگاه داده موجود است؛ '+(view.policies?.patterns.length||0)+' سیاست نمونه و '+(view.calendars?.calendars.length||0)+' تقویم. سناریوها را اجرا کنید تا تصمیم واقعی موتور را ببینید.');}
 async function load(){try{render(await request());}catch(error){message(error.message,true);}}
 form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const reason=form.elements.reason.value.trim();if(!reason)throw Error('دلیل ایجاد دادهٔ آموزشی را بنویسید.');render(await request('',{reason}));message('سازمان الگو ثبت شد. از لینک ساختار و تقویم وارد سازمان شوید یا سناریوهای زیر را اجرا کنید.');}catch(error){message(error.message,true);}finally{button.disabled=false;}};
 run.onclick=async()=>{run.disabled=true;const box=$('org-template-results');box.replaceChildren(node('p','سناریوها با اطلاعات فعلی سرور در حال اجرا هستند…','muted'));try{const response=await request('/scenarios');box.replaceChildren(node('h4',response.passed+' از '+response.total+' سناریو مطابق انتظار است.'),node('p','این نتایج با پیش‌نویس‌های آموزشی محاسبه شده‌اند؛ هیچ انتشار سیاست یا عملیات واقعی انجام نمی‌شود.','org-calendar-note'));for(const item of response.results){const card=node('article',null,'org-position');card.append(node('h4',item.scenario.title),node('span',item.passed?'مطابق انتظار':'نیازمند بررسی','pill '+(item.passed?'teal':'amber')),node('p','انتظار: '+item.scenario.expectedDecision+' · نتیجهٔ موتور: '+item.actual.decision),node('p','علت سرور: '+item.actual.reason),node('p',lessonByKey.get(item.scenario.lesson)||item.scenario.lesson),scenarioValue('زمان دقیق: ',item.scenario.at),scenarioValue('هویت آموزشی: ',item.scenario.subject),scenarioValue('عملیات: ',item.scenario.permission));box.append(card);}}catch(error){box.replaceChildren(node('p',error.message,'org-error'));}finally{run.disabled=false;}};
 load();
})();
